// Re-attach the person the classification belongs to, and guard the LLM output.
// $('Has skills?') is indexed by item, so classification N maps to person N.
const VALID = ['automation-heavy', 'web-dev', 'data', 'generalist'];
const minConfidence = $('Config').first().json.min_confidence ?? 0.6;
const out = [];

for (let i = 0; i < items.length; i++) {
  const person = $('Has skills?').all()[i].json;
  const raw = items[i].json.output ?? items[i].json;
  const category = String(raw.skill_category || '').trim().toLowerCase();
  const confidence = Number(raw.confidence);

  const valid = VALID.includes(category);
  const confident = Number.isFinite(confidence) && confidence >= minConfidence;

  out.push({
    json: {
      person_id: person.person_id,
      full_name: person.full_name,
      skills: person.skills,
      skill_category: valid ? category : 'generalist',
      confidence: Number.isFinite(confidence) ? confidence : 0,
      reason: raw.reason || '',
      accepted: valid && confident,
      note: !valid
        ? `model returned an out-of-vocabulary category: ${raw.skill_category}`
        : !confident
          ? `confidence ${confidence} below threshold ${minConfidence}`
          : 'ok',
    },
  });
}

return out;

// Everything the flow refused to write, kept as one payload for a human.
return [{ json: {
  needs_review: items.map(i => ({
    person_id: i.json.person_id,
    full_name: i.json.full_name,
    skills: i.json.skills,
    proposed: i.json.skill_category,
    confidence: i.json.confidence,
    note: i.json.note,
  })),
  count: items.length,
} }];
